for tk,(entry,target,stop,note) in UP.items():
    m = re.search(r"\{ticker:'"+tk+r"',.*?\n", src)
    if not m: print(f'ERROR: {tk}'); sys.exit(1)
    line=m.group(0); new=line
    new = re.sub(r"entry:'[^']*'", "entry:'"+entry+"'", new)
    new = re.sub(r"target:'[^']*'", "target:'"+target+"'", new)
    new = re.sub(r"stop:'[^']*'", "stop:'"+stop+"'", new)
    new = re.sub(r"note:'(?:[^'\\]|\\.)*'\}", "note:'"+note.replace('\\','\\\\').replace("'","\\'")+"'}", new)
    if new==line: print(f'ERROR: {tk} unchanged'); sys.exit(1)
    src = src.replace(line,new,1); print(f'  {tk}: {entry} stop {stop} tgt {target}')
open(FILE,'w').write(src); print('OK - all 13 zones recalibrated'); os.remove(FILE+'.bak')
